  return esc(l.slice(0, cut)) + l.slice(cut).split(" · ").map((n) => { const d = n.replace(/[^\d*#+]/g, ""); return d ? `<a href="tel:${esc(d)}">${esc(n)}</a>` : esc(n); }).join(" · ");
